/**
 * CablePatternInjector - Injects cable pattern events into StitchPlan rows
 * 
 * This utility processes cable pattern placements and adds CableCrossEvent
 * annotations to the appropriate rows in a stitch plan.
 */

import { CablePattern, CablePatternPlacement, CableCrossEvent, getCableWidth } from '../models/CablePattern';
import { StitchRow } from './stitchPlanGenerator';

/**
 * Inject cable pattern events into a stitch plan
 * 
 * @param rows - Array of StitchRow objects to modify
 * @param placements - Array of cable pattern placements
 * @param patterns - Map of pattern IDs to CablePattern objects
 * @returns Modified rows with cable cross events added
 */
export function injectCablePatterns(
  rows: StitchRow[],
  placements: CablePatternPlacement[],
  patterns: Map<string, CablePattern>
): StitchRow[] {
  // Clone rows to avoid mutation
  const modifiedRows = rows.map(row => ({ ...row }));

  for (const placement of placements) {
    const pattern = patterns.get(placement.patternId);
    if (!pattern) {
      console.warn(`Cable pattern not found: ${placement.patternId}`);
      continue;
    }

    // Determine the effective repeat interval
    const repeatRows = placement.customRepeatRows || pattern.repeatRows;
    const direction = placement.customDirection || pattern.direction;
    const startRow = placement.startRow || 0;
    const endRow = placement.endRow || modifiedRows.length - 1;

    // Calculate cable width to validate placement
    const cableWidth = getCableWidth(pattern);

    // Inject cable crosses at the appropriate intervals
    for (let rowIndex = startRow; rowIndex <= endRow; rowIndex++) {
      // Check if this is a cable crossing row
      const rowsSinceStart = rowIndex - startRow;
      
      // Cable crosses happen on the first row and then every repeatRows
      if (rowsSinceStart % repeatRows === 0) {
        const row = modifiedRows[rowIndex];
        
        // Validate that cable fits within row width
        if (placement.startStitch + cableWidth > row.totalStitches) {
          console.warn(
            `Cable placement exceeds row width at row ${row.rowNumber}: ` +
            `startStitch=${placement.startStitch}, cableWidth=${cableWidth}, rowWidth=${row.totalStitches}`
          );
          continue;
        }

        // Initialize cableCrosses array if not present
        if (!row.cableCrosses) {
          row.cableCrosses = [];
        }

        // Handle traveling cables with offset
        const effectiveStartIndex = placement.startStitch + 
          (pattern.offset ? (pattern.offset * Math.floor(rowsSinceStart / repeatRows)) : 0);

        // Create cable cross event
        const cableEvent: CableCrossEvent = {
          startIndex: effectiveStartIndex,
          leftGroup: pattern.leftGroup,
          rightGroup: pattern.rightGroup,
          middleGroup: pattern.middleGroup,
          direction: direction,
          patternId: pattern.id,
          label: placement.label || pattern.name
        };

        row.cableCrosses.push(cableEvent);
      }
    }
  }

  return modifiedRows;
}

/**
 * Apply cable crossing to a row's stitch order
 * 
 * This function reorders stitches according to a cable cross event.
 * Used by actualizers to generate correct stitch sequences.
 * 
 * @param stitches - Array of stitch data (or indices) to reorder
 * @param cableEvent - Cable cross event describing the crossing
 * @returns Reordered stitch array
 */
export function applyCableCross<T>(stitches: T[], cableEvent: CableCrossEvent): T[] {
  const { startIndex, leftGroup, rightGroup, middleGroup, direction } = cableEvent;
  
  // Clone array to avoid mutation
  const result = [...stitches];
  
  // Extract the stitch groups
  const totalWidth = leftGroup + rightGroup + (middleGroup || 0);
  const endIndex = startIndex + totalWidth;
  
  // Validate indices
  if (endIndex > stitches.length) {
    console.warn(`Cable cross exceeds stitch array bounds: startIndex=${startIndex}, width=${totalWidth}, length=${stitches.length}`);
    return result;
  }

  if (middleGroup) {
    // Three-group braid pattern
    const left = stitches.slice(startIndex, startIndex + leftGroup);
    const middle = stitches.slice(startIndex + leftGroup, startIndex + leftGroup + middleGroup);
    const right = stitches.slice(startIndex + leftGroup + middleGroup, endIndex);
    
    // Alternate crossing for braids
    if (direction === 'R') {
      // Right cross: middle, left, right
      result.splice(startIndex, totalWidth, ...middle, ...left, ...right);
    } else {
      // Left cross: right, middle, left
      result.splice(startIndex, totalWidth, ...right, ...middle, ...left);
    }
  } else {
    // Two-group crossing
    const left = stitches.slice(startIndex, startIndex + leftGroup);
    const right = stitches.slice(startIndex + leftGroup, endIndex);
    
    if (direction === 'R') {
      // Right cross: right group worked first (held to back)
      result.splice(startIndex, totalWidth, ...right, ...left);
    } else {
      // Left cross: left group worked first (held to front)
      result.splice(startIndex, totalWidth, ...right, ...left);
    }
  }
  
  return result;
}

/**
 * Generate cable crossing instruction text for hand knitting
 * 
 * @param cableEvent - Cable cross event
 * @param pattern - Optional cable pattern for additional context
 * @returns Human-readable instruction text
 */
export function generateCableInstruction(
  cableEvent: CableCrossEvent,
  pattern?: CablePattern
): string {
  const { leftGroup, rightGroup, middleGroup, direction, startIndex } = cableEvent;
  
  if (middleGroup) {
    // Braid pattern
    return `${leftGroup}x${middleGroup}x${rightGroup} braid at st ${startIndex + 1}`;
  }
  
  const totalStitches = leftGroup + rightGroup;
  const crossType = direction === 'L' ? 'LC' : 'RC';
  
  // Standard cable notation: C4F = Cable 4 Front (left cross)
  const cableNotation = `C${totalStitches}${direction === 'L' ? 'F' : 'B'}`;
  
  return `${cableNotation} (${leftGroup}/${rightGroup} ${crossType}) at st ${startIndex + 1}`;
}

/**
 * Get cable symbol for visualization
 * 
 * @param cableEvent - Cable cross event
 * @returns Unicode symbol representing the cable cross
 */
export function getCableSymbol(cableEvent: CableCrossEvent): string {
  const { direction, middleGroup } = cableEvent;
  
  if (middleGroup) {
    return '⋈'; // Braid symbol
  }
  
  return direction === 'L' ? '⤺' : '⤻';
}

/**
 * Validate cable pattern placements for conflicts
 * 
 * @param placements - Array of cable pattern placements to validate
 * @param patterns - Map of pattern IDs to CablePattern objects
 * @param rowWidth - Width of the row in stitches
 * @returns Array of validation error messages (empty if valid)
 */
export function validateCablePlacements(
  placements: CablePatternPlacement[],
  patterns: Map<string, CablePattern>,
  rowWidth: number
): string[] {
  const errors: string[] = [];
  
  // Check each placement individually
  for (const placement of placements) {
    const pattern = patterns.get(placement.patternId);
    if (!pattern) {
      errors.push(`Unknown pattern: ${placement.patternId}`);
      continue;
    }
    
    const cableWidth = getCableWidth(pattern);
    if (placement.startStitch + cableWidth > rowWidth) {
      errors.push(
        `Cable "${pattern.name}" at stitch ${placement.startStitch} exceeds row width ` +
        `(cable width: ${cableWidth}, row width: ${rowWidth})`
      );
    }
  }
  
  // Check for overlapping cables
  for (let i = 0; i < placements.length; i++) {
    for (let j = i + 1; j < placements.length; j++) {
      const p1 = placements[i];
      const p2 = placements[j];
      
      const pattern1 = patterns.get(p1.patternId);
      const pattern2 = patterns.get(p2.patternId);
      
      if (!pattern1 || !pattern2) continue;
      
      const width1 = getCableWidth(pattern1);
      const width2 = getCableWidth(pattern2);
      
      const end1 = p1.startStitch + width1;
      const end2 = p2.startStitch + width2;
      
      // Check if ranges overlap
      if (
        (p1.startStitch < end2 && end1 > p2.startStitch) ||
        (p2.startStitch < end1 && end2 > p1.startStitch)
      ) {
        errors.push(
          `Cable patterns overlap: "${pattern1.name}" (stitches ${p1.startStitch}-${end1}) ` +
          `and "${pattern2.name}" (stitches ${p2.startStitch}-${end2})`
        );
      }
    }
  }
  
  return errors;
}

export default {
  injectCablePatterns,
  applyCableCross,
  generateCableInstruction,
  getCableSymbol,
  validateCablePlacements
};
